mapper.select:
/* LeaveRefusalMapper.selectNextRefusalId */
SELECT CONCAT('LR', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'LEAVE_REFUSAL_ID'))
  FROM DUAL

mapper.insert:
/* LeaveRefusalMapper.insertRefusalLog */
INSERT INTO TB_LEAVE_REFUSAL_LOG (
      REFUSAL_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , TARGET_YMD
    , EVENT_TYPE
    , ATTEMPT_TYPE
    , RELATED_NOTI_ID
    , RELATED_ATTD_ID
    , RELATED_LEAVE_ID
    , DETECT_DTIME
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
    , DEDUP_KEY
)
VALUES (
      #{refusalId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{targetYmd}
    , #{eventType}
    , #{attemptType}
    , #{relatedNotiId}
    , #{relatedAttdId}
    , #{relatedLeaveId}
    , NOW()NULL
    , 'N'
    , #{insertNo}
    , NOW()
    , #{dedupKey}
) AS NEW
ON DUPLICATE KEY UPDATE
      UPDATE_DATE = NOW()

mapper.select:
/* LeaveRefusalMapper.selectSiteRefusalAdmins */ SELECT DISTINCT M.USER_CD FROM (
SELECT U.USER_CD FROM TB_USER U INNER JOIN TB_USER_SITE_AUTH SA ON U.CMPNY_CD = SA.CMPNY_CD AND U.USER_CD = SA.USER_CD AND SA.SITE_CD = #{siteCd} AND SA.USE_YN = 'Y' WHERE U.CMPNY_CD = #{cmpnyCd} AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01' AND U.AUTH_CD IN
#{authCd}
UNION
SELECT A.USER_CD FROM TB_USER A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.USE_YN = 'Y' AND A.ACCOUNT_STATUS = '01' AND A.USER_CD IN ( SELECT N.MAIN_ADMIN_CD FROM TB_SITE_NODE N INNER JOIN TB_USER W ON W.CMPNY_CD = N.CMPNY_CD AND W.NODE_CD = N.NODE_CD AND W.SITE_CD = N.SITE_CD WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND W.USER_CD = #{userCd} AND NULLIF(TRIM(N.MAIN_ADMIN_CD), '') IS NOT NULL UNION SELECT N.SUB_ADMIN_CD FROM TB_SITE_NODE N INNER JOIN TB_USER W ON W.CMPNY_CD = N.CMPNY_CD AND W.NODE_CD = N.NODE_CD AND W.SITE_CD = N.SITE_CD WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND W.USER_CD = #{userCd} AND NULLIF(TRIM(N.SUB_ADMIN_CD), '') IS NOT NULL ) ) M
